using W=System.Windows;
using C=System.Windows.Controls;
using M=System.Windows.Media;
using U=VelvetVoice.UiControls;
namespace CombinedStudio;
internal sealed class ThemesPage:C.ScrollViewer {
 readonly AppThemeService service;readonly C.TextBlock current=U.Text("",15,U.Accent),status=U.Text("",12,U.Muted);readonly Dictionary<string,C.Button> buttons=new();
 internal ThemesPage(AppThemeService service){this.service=service;VerticalScrollBarVisibility=C.ScrollBarVisibility.Auto;HorizontalScrollBarVisibility=C.ScrollBarVisibility.Disabled;var page=new C.StackPanel{Margin=new W.Thickness(30,24,30,24),MaxWidth=1100};Content=page;
  page.Children.Add(U.Text("THEMES",32));page.Children.Add(U.Text("Give your workspace a different mood. Themes apply across the app immediately.",14,U.Muted));page.Children.Add(current);
  var gallery=new C.WrapPanel();foreach(var theme in ThemePalette.Themes){var content=new C.StackPanel();var sample=new C.Grid{Height=125,Background=new M.SolidColorBrush(theme.Color("Bg")),Margin=new W.Thickness(0,0,0,14)};sample.ColumnDefinitions.Add(new(){Width=new W.GridLength(54)});sample.ColumnDefinitions.Add(new(){Width=new W.GridLength(1,W.GridUnitType.Star)});
   var rail=new C.StackPanel{Background=new M.SolidColorBrush(theme.Color("Sidebar")),Margin=new W.Thickness(0)};rail.Children.Add(new C.Border{Height=9,Margin=new W.Thickness(10,15,10,12),Background=new M.SolidColorBrush(theme.Color("Accent")),CornerRadius=new W.CornerRadius(3)});for(int i=0;i<3;i++)rail.Children.Add(new C.Border{Height=5,Margin=new W.Thickness(10,0,10,9),Background=new M.SolidColorBrush(theme.Color("Muted"))});sample.Children.Add(rail);
   var cards=new C.StackPanel{Margin=new W.Thickness(12)};C.Grid.SetColumn(cards,1);cards.Children.Add(new C.TextBlock{Text="YAIOpc",Foreground=new M.SolidColorBrush(theme.Color("Ink")),FontSize=15,Margin=new W.Thickness(0,0,0,10)});cards.Children.Add(new C.Border{Height=40,Background=new M.SolidColorBrush(theme.Color("Panel")),BorderBrush=new M.SolidColorBrush(theme.Color("Line")),BorderThickness=new W.Thickness(1),CornerRadius=new W.CornerRadius(6),Child=new C.Border{Height=5,Width=65,HorizontalAlignment=W.HorizontalAlignment.Left,Margin=new W.Thickness(10),Background=new M.SolidColorBrush(theme.Color("Accent"))}});sample.Children.Add(cards);content.Children.Add(sample);content.Children.Add(U.Text(theme.Name,18));content.Children.Add(U.Text(theme.Description,12,U.Muted));var button=new C.Button{Content="Apply theme",MinHeight=40,Margin=new W.Thickness(0,8,0,0)};button.Click+=(_,_)=>{try{service.Select(theme.Id);status.Text="Saved. This theme will return next time you open YAIOpc.";}catch(Exception error){status.Text=error.Message;}};W.Automation.AutomationProperties.SetName(button,"Apply "+theme.Name+" theme");buttons.Add(theme.Id,button);content.Children.Add(button);var card=U.Card(content);card.Width=300;card.Margin=new W.Thickness(0,0,16,16);gallery.Children.Add(card);
  }page.Children.Add(gallery);var reset=new C.Button{Content="Restore original Copper theme",MinHeight=42,HorizontalAlignment=W.HorizontalAlignment.Left,Margin=new W.Thickness(0,4,0,12)};reset.Click+=(_,_)=>{try{service.Select("copper");}catch(Exception error){status.Text=error.Message;}};page.Children.Add(reset);page.Children.Add(U.Text("Themes change the interface palette. Crosshair designs, artwork, audio settings, and display settings keep their own values.",12,U.Muted));page.Children.Add(status);service.Changed+=Refresh;Refresh();status.Text=service.Error;
 }
 void Refresh(){current.Text="Current theme: "+ThemePalette.Current.Name;foreach(var pair in buttons){bool active=pair.Key==ThemePalette.Current.Id;pair.Value.Content=active?"Selected":"Apply theme";pair.Value.IsEnabled=!active;}}
 internal void Select(string id)=>service.Select(id);
}
